UPDATE ADM_USER_MST
   SET USE_YN = 'N',
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by}
 WHERE USER_SEQ = #{user_seq}

UPDATE ADM_USER_MST
   SET USER_NM = #{user_nm},
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by}
 WHERE LOGIN_ID = #{login_id}
   AND NVL(USE_YN, 'Y') = 'Y'
